import{_ as l,a0 as o,w as d,s as n,ao as r,I as p,x as s,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"为你的 Fedora 系统增添发音功能 | LCTT x X-CMD","titleTemplate":false,"description":"为你的 Fedora 系统增添发音功能 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为你的 Fedora 系统增添发音功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为你的 Fedora 系统增添发音功能 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170804 Add speech to your Fedora system","title":"为你的 Fedora 系统增添发音功能","tag":"201801","desc":""},"relativePath":"201801/20170804 Add speech to your Fedora system.md","filePath":"[post].md"}'),h={name:"201801/20170804 Add speech to your Fedora system.md"};function g(k,e,u,f,c,b){const a=o("Link");return d(),n("div",null,[e[13]||(e[13]=r('<h1 id="为你的-fedora-系统增添发音功能" tabindex="-1">为你的 Fedora 系统增添发音功能 <a class="header-anchor" href="#为你的-fedora-系统增添发音功能" aria-label="Permalink to “为你的 Fedora 系统增添发音功能”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/08/espeak-945x400.png" alt=""></p><p>Fedora 工作站默认带有一个小软件，叫做 espeak。它是一个声音合成器 -- 也就是转换文本为声音的软件。</p><p>在当今这个世界，发音设备已经非常普遍了。在智能电话、Amazon Alexa，甚至火车站的公告栏中都有声音合成器。而且，现在合成声音已经跟人类的声音很类似了。我们生活在 80bandaid 的科幻电影里！</p><p>与前面提到的这些工具相比，espeak 的发音听起来有一点原始。但最终 espeak 可以产生不错的发音效果。而且不管你觉得它有没有用，至少它可以给你带来一些乐趣。</p><h3 id="运行-espeak" tabindex="-1">运行 espeak <a class="header-anchor" href="#运行-espeak" aria-label="Permalink to “运行 espeak”">​</a></h3><p>你可以在命令行为 espeak 设置各种参数。包括：</p><ul><li>振幅（<code>-a</code>）</li><li>音高调整 （<code>-p</code>）</li><li>读句子的速度 （<code>-s</code>）</li><li>单词间的停顿时间 （<code>-g</code>）</li></ul><p>每个选项都能产生不同的效果，你可以通过调整它们来让发音更加清晰。</p><p>你也可以通过命令行选项来选择不同的变音。比如，<code>-ven+m3</code> 表示另一种英式男音，而 <code>-ven+f1</code> 表示英式女音。你也可以尝试其他语言的发音。运行下面命令可以查看支持的语言列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>espeak --voices</span></span></code></pre></div><p>要注意，很多非英语的语言发音现在还处于实验阶段。</p><p>若要创建相应的 WAV 文件而不是真的讲出来，则可以使用 <code>-w</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>espeak -w out.wav &quot;Audio file test&quot;</span></span></code></pre></div><p>espeak 还能读出文件的内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>espeak -f plaintextfile</span></span></code></pre></div><p>你也可以通过标准输入传递要发音的文本。举个简单的例子，通过这种方式，你可以创建一个发音盒子，当事件发生时使用声音通知你。你的备份完成了？将下面命令添加到脚本的最后试试效果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;Backup completed&quot; | espeak -s 160 -a 100 -g 4</span></span></code></pre></div><p>假如有日志文件中出现错误了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tail -1F /your/log/file | grep --line-buffered &#39;ERROR&#39; | espeak</span></span></code></pre></div><p>或者你也可以创建一个报时钟表，每分钟报一次时：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>while true; do date +%S | grep &#39;00&#39; &amp;&amp; date +%H：%M | espeak; sleep 1; done</span></span></code></pre></div><p>你会发现，espeak 的使用场景仅仅受你的想象所限制。享受你这会发音的 Fedora 系统吧！</p><hr>',24)),p("p",null,[e[1]||(e[1]=s("via: ",-1)),t(a,{href:"https://fedoramagazine.org/add-speech-fedora-system/"},{default:i(()=>[...e[0]||(e[0]=[s("https://fedoramagazine.org/add-speech-fedora-system/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=s("作者：",-1)),t(a,{href:"http://alciregi.id.fedoraproject.org/"},{default:i(()=>[...e[2]||(e[2]=[s("Alessio Ciregia",-1)])]),_:1}),e[6]||(e[6]=s(" 译者：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[7]||(e[7]=s(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=s("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[s("Linux中国",-1)])]),_:1}),e[12]||(e[12]=s(" 荣誉推出",-1))])])}const x=l(h,[["render",g]]);export{C as __pageData,x as default};
